export const icono = (nombre, clase = "ico", { lleno = false } = {}) =>
  `<svg class="${clase}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">${(lleno && LLENO[nombre]) || P[nombre] || ""}</svg>`;
/** Los dos (de línea y relleno) para la navegación: el CSS muestra el relleno en la sección elegida. */
export const iconoNav = (nombre) => `${icono(nombre, "ico normal")}${icono(nombre, "ico lleno", { lleno: true })}`;
